<script setup>
import { vCanAction } from '../services/permission-directives.js'
import { computed, onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useQuasar, copyToClipboard } from 'quasar'
import { http, unwrap, errorMessage, fetchAll } from '../services/http.js'
import SiteDocumentFrame from './SiteDocumentFrame.vue'
import { siteSlug } from '../services/site-slug.js'
const $q=useQuasar(),items=ref([]),contacts=ref([]),groups=ref([]),loading=ref(false),saving=ref(false),dialog=ref(false),editing=ref(null),preview=ref(null),previewing=ref(false),device=ref('desktop'),file=ref(null),uploading=ref(false),search=ref(''),temporary=ref(false),expiresLocal=ref('')
const empty=()=>({name:'',slug:'',title:'',visibility:'public',active:true,expiresAt:null,contactIds:[],groupIds:[],sections:[{title:'',format:'text',text:''}],css:'',media:[],buttons:[]})
const form=reactive(empty())
const slugEdited=ref(false),previewError=ref(''),previewUpdated=ref(false)
let previewTimer,previewController,previewVersion=0
function markSlugEdited(){slugEdited.value=true}
const routePreview=computed(()=>'/notificacao/'+(form.slug||siteSlug(form.name)))
const visible=computed(()=>items.value.filter(item=>item.name.toLowerCase().includes(search.value.toLowerCase())))
const choices=rows=>rows.map(item=>({label:item.displayName||item.name||item.email||item.phone||'Contato',value:item.id||item._id}))
async function load(){loading.value=true;try{items.value=unwrap(await http.get('/site-templates')).items}catch(cause){$q.notify({type:'negative',message:errorMessage(cause)})}finally{loading.value=false}}
async function edit(item){editing.value=item?.id||null;preview.value=null;previewError.value='';previewUpdated.value=false;slugEdited.value=Boolean(item);Object.assign(form,empty());temporary.value=false;expiresLocal.value='';dialog.value=true;file.value=null;try{if(item){const value=unwrap(await http.get('/site-templates/'+item.id));for(const key of Object.keys(empty()))form[key]=value[key]??empty()[key];temporary.value=Boolean(value.expiresAt);if(value.expiresAt){const d=new Date(value.expiresAt);expiresLocal.value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)}};[contacts.value,groups.value]=await Promise.all([fetchAll('/contacts'),fetchAll('/contact-groups')])}catch(cause){$q.notify({type:'negative',message:errorMessage(cause)})}}
function payload(){return{...form,expiresAt:temporary.value?new Date(expiresLocal.value).toISOString():null}}
async function save(){saving.value=true;try{if(temporary.value&&(!expiresLocal.value||new Date(expiresLocal.value)<=new Date()))throw Error('Escolha uma data futura para retirar o site do ar.');if(editing.value)await http.put('/site-templates/'+editing.value,payload());else await http.post('/site-templates',payload());dialog.value=false;await load();$q.notify({type:'positive',message:'Site salvo. O link já está disponível para seus templates.'})}catch(cause){$q.notify({type:'negative',message:errorMessage(cause)})}finally{saving.value=false}}
async function showPreview({automatic=false}={}){
  clearTimeout(previewTimer);previewController?.abort();const version=++previewVersion
  previewController=new AbortController();previewing.value=true;previewError.value=''
  try{
    const input={...form,name:form.name.trim()||'Prévia',title:form.title.trim()||form.name.trim()||'Sua notificação',expiresAt:null,visibility:'public',contactIds:[],groupIds:[],buttons:form.buttons.filter(button=>button.label.trim()&&/^(https:\/\/|mailto:|tel:)/i.test(button.url))}
    const result=unwrap(await http.post('/site-templates/preview',input,{signal:previewController.signal}))
    if(version===previewVersion){preview.value=result;previewUpdated.value=true}
  }catch(cause){if(version===previewVersion&&cause.code!=='ERR_CANCELED'){previewError.value=errorMessage(cause,'Revise o conteúdo para atualizar a prévia.');if(!automatic)$q.notify({type:'negative',message:previewError.value})}}
  finally{if(version===previewVersion)previewing.value=false}
}
watch(()=>form.name,value=>{if(!slugEdited.value)form.slug=value?siteSlug(value):''})
watch(form,()=>{if(dialog.value){clearTimeout(previewTimer);previewTimer=setTimeout(()=>showPreview({automatic:true}),550)}},{deep:true})
watch(dialog,open=>{clearTimeout(previewTimer);if(open)previewTimer=setTimeout(()=>showPreview({automatic:true}),100);else{previewController?.abort();previewVersion++;previewing.value=false}})
onBeforeUnmount(()=>{clearTimeout(previewTimer);previewController?.abort();previewVersion++})
async function upload(){if(!file.value)return;uploading.value=true;try{const data=new FormData();data.append('file',file.value);const uploaded=unwrap(await http.post('/site-templates/media',data,{timeout:120000}));form.media.push(uploaded);file.value=null;preview.value=null}catch(cause){$q.notify({type:'negative',message:errorMessage(cause)})}finally{uploading.value=false}}
async function copy(item){try{await copyToClipboard(item.url);$q.notify({type:'positive',message:'Link copiado.'})}catch{$q.notify({message:item.url})}}
function remove(item){$q.dialog({title:'Retirar este site do ar?',message:'O link deixará de exibir o conteúdo. As campanhas e os templates vinculados serão preservados.',cancel:true,ok:{label:'Retirar do ar',color:'negative'}}).onOk(async()=>{try{await http.delete('/site-templates/'+item.id);await load()}catch(cause){$q.notify({type:'negative',message:errorMessage(cause)})}})}
onMounted(load)
defineExpose({create:()=>edit()})
</script>
<template><section class="site-library"><header><div><h2><q-icon name="public"/> Sites de notificação</h2><p>Uma página completa para acompanhar o resumo enviado pelo WhatsApp, Telegram ou Gmail.</p></div><q-btn color="purple" unelevated no-caps icon="add" label="Novo site" v-can-action="'templates.create'" @click="edit()"/></header><q-input v-model="search" outlined dense clearable label="Buscar site" @clear="search=''" class="q-mb-md"/><div class="site-library-grid"><q-card v-for="item in visible" :key="item.id" flat bordered class="site-library-card"><q-card-section><q-icon name="public" size="32px" color="purple"/><h3>{{item.name}}</h3><q-badge :color="!item.active||item.expired?'grey-7':item.visibility==='private'?'purple':'positive'">{{!item.active||item.expired?'Fora do ar':item.visibility==='private'?'Privado':'Público'}}</q-badge><p>{{item.expiresAt?'Disponível até '+new Date(item.expiresAt).toLocaleString('pt-BR'):'Sem expiração automática'}}</p><small>{{item.url}}</small></q-card-section><q-card-actions><q-btn flat no-caps color="purple" icon="edit" label="Editar" v-can-action="'templates.edit'" @click="edit(item)"/><q-btn flat round icon="content_copy" aria-label="Copiar link" @click="copy(item)"/><q-btn flat round icon="open_in_new" aria-label="Abrir site" :href="item.url" target="_blank" rel="noopener noreferrer"/><q-space/><q-btn flat round color="negative" icon="delete" aria-label="Retirar site do ar" v-can-action="'templates.delete'" @click="remove(item)"/></q-card-actions></q-card></div><div v-if="!items.length" class="site-library-empty">{{loading?'Carregando sites…':'Crie seu primeiro site para compartilhar o conteúdo completo das notificações.'}}</div>
<q-dialog v-model="dialog" persistent :maximized="$q.screen.lt.md"><q-card class="site-editor"><q-card-section class="row items-center"><div class="col"><div class="text-h6">{{editing?'Editar site':'Novo site de notificação'}}</div><div class="text-caption text-grey-7">Texto completo, arquivos e até 20 botões em um link.</div></div><q-btn flat round icon="close" :disable="uploading||saving" v-close-popup/></q-card-section><q-separator/><q-form @submit="save"><div class="site-editor-grid"><div class="site-editor-fields"><h3>Identificação e acesso</h3><q-input v-model="form.name" outlined label="Nome na biblioteca" maxlength="160" :rules="[v=>!!v.trim()||'Informe o nome']"/><q-input v-model="form.slug" outlined label="Endereço da página (slug)" maxlength="100" :hint="routePreview+' · endereços anteriores continuam funcionando'" @update:model-value="markSlugEdited" @blur="form.slug=siteSlug(form.slug||form.name)"><template #prepend><q-icon name="link" color="purple"/></template></q-input><q-input v-model="form.title" outlined label="Título em destaque na página" maxlength="240" :rules="[v=>!!v.trim()||'Informe o título']"/><q-select v-model="form.visibility" outlined emit-value map-options :options="[{label:'Público · qualquer pessoa com o link',value:'public'},{label:'Privado · login e destinatário autorizado',value:'private'}]" label="Quem pode visualizar"/><template v-if="form.visibility==='private'"><q-select v-model="form.contactIds" outlined multiple use-chips emit-value map-options :options="choices(contacts)" label="Contatos autorizados"/><q-select v-model="form.groupIds" outlined multiple use-chips emit-value map-options :options="choices(groups)" label="Grupos autorizados"/><p class="site-help">O acesso usa o login do Meu perfil e confere o contato ou a participação atual em um destes grupos. Vincule pelo menos um contato ou grupo.</p></template><div class="site-switches"><q-toggle v-model="form.active" label="Site no ar"/><q-toggle v-model="temporary" label="Página temporária"/></div><q-input v-if="temporary" v-model="expiresLocal" outlined type="datetime-local" label="Retirar do ar automaticamente" stack-label hint="Horário deste dispositivo. O servidor bloqueia o acesso após a data, inclusive aos arquivos."/>
<h3>Conteúdo completo</h3><section v-for="(section,index) in form.sections" :key="index" class="site-section-editor"><div class="row items-center"><b class="col">Seção {{index+1}}</b><q-btn v-if="form.sections.length>1" flat round dense icon="delete" color="negative" aria-label="Remover seção" @click="form.sections.splice(index,1)"/></div><q-input v-model="section.title" outlined dense label="Título da seção (opcional)" maxlength="240"/><q-select v-model="section.format" outlined dense emit-value map-options :options="[{label:'Texto / TXT',value:'text'},{label:'Markdown',value:'markdown'},{label:'HTML',value:'html'}]" label="Formato"/><q-input v-model="section.text" outlined type="textarea" rows="8" maxlength="100000" label="Texto da notificação" hint="Enter preserva as quebras de linha. HTML não executa scripts."/></section><q-btn outline no-caps color="purple" icon="add" label="Adicionar seção" :disable="form.sections.length>=30" @click="form.sections.push({title:'',format:'text',text:''})"/>
<h3>Imagens, vídeos e documentos</h3><p class="site-help">JPG/PNG até 5 MB, vídeo MP4 até 16 MB e documentos até 25 MB. Os arquivos seguem as mesmas regras de acesso da página.</p><q-file v-model="file" outlined label="Escolher arquivo" :disable="uploading||form.media.length>=20" accept=".jpg,.jpeg,.png,.mp4,.3gp,.pdf,.txt,.doc,.docx,.xls,.xlsx,.ppt,.pptx"/><q-btn outline no-caps color="purple" icon="upload" label="Anexar arquivo" :loading="uploading" :disable="!file||form.media.length>=20" v-can-action="'templates.import'" @click="upload"/><q-list bordered separator v-if="form.media.length"><q-item v-for="(media,index) in form.media" :key="media.id"><q-item-section avatar><q-icon :name="media.type==='image'?'image':media.type==='video'?'movie':'description'" color="purple"/></q-item-section><q-item-section>{{media.name}}</q-item-section><q-item-section side><q-btn flat round dense icon="close" aria-label="Remover mídia do site" @click="form.media.splice(index,1);preview=null"/></q-item-section></q-item></q-list>
<h3>Botões · {{form.buttons.length}}/20</h3><div v-for="(button,index) in form.buttons" :key="index" class="site-button-editor"><q-input v-model="button.label" outlined dense label="Texto do botão" maxlength="80"/><q-input v-model="button.url" outlined dense label="Link HTTPS, e-mail ou telefone"/><q-btn flat round color="negative" icon="delete" aria-label="Remover botão" @click="form.buttons.splice(index,1)"/></div><q-btn outline no-caps color="purple" icon="add_link" label="Adicionar botão" :disable="form.buttons.length>=20" @click="form.buttons.push({label:'',url:''})"/><q-expansion-item icon="code" label="CSS personalizado" class="q-mt-md"><q-input v-model="form.css" outlined type="textarea" rows="7" maxlength="30000" label="CSS" hint="Classes: main, header, section, .buttons e .document. Pode usar @media; recursos externos são bloqueados."/></q-expansion-item>
</div><aside class="site-editor-preview"><div class="row items-center q-gutter-sm"><strong class="col">Prévia em tempo real</strong><q-btn-toggle v-model="device" flat dense :options="[{icon:'computer',value:'desktop'},{icon:'smartphone',value:'mobile'}]"/></div><q-btn no-caps outline color="purple" icon="refresh" label="Atualizar prévia" class="q-my-sm" :loading="previewing" @click="showPreview"/><p class="site-preview-status" role="status">{{previewing?'Atualizando…':previewError|| (previewUpdated?'Atualizada automaticamente enquanto você escreve.':'Preparando prévia…')}}</p><div :class="{'site-preview-mobile':device==='mobile'}"><SiteDocumentFrame v-if="preview" :content="preview" compact/><p v-else class="site-help">Digite seu conteúdo. A prévia aparece automaticamente, sem publicar alterações.</p></div></aside></div><q-card-actions align="right" class="site-editor-actions"><q-btn flat no-caps label="Cancelar" :disable="saving||uploading" v-close-popup/><q-btn color="purple" no-caps v-can-action="editing ? 'templates.edit' : 'templates.create'" type="submit" label="Salvar site" :loading="saving" :disable="uploading"/></q-card-actions></q-form></q-card></q-dialog></section></template>
<style scoped>.site-library>header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:20px}.site-library h2{font-size:25px;line-height:1.3;color:#703694;margin:0}.site-library p{font-size:13px;color:#7b7184}.site-library-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:16px}.site-library-card{border-radius:16px;border-color:#dfcce9;min-width:0}.site-library-card h3{font-size:19px;line-height:1.4}.site-library-card small{display:block;font-size:11px;color:#826d90;overflow-wrap:anywhere}.site-library-empty{padding:40px;text-align:center;color:#86798d}.site-editor{width:1280px;max-width:97vw;max-height:94dvh;border-radius:20px;overflow:auto}.site-editor-grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,.9fr)}.site-editor-fields{padding:20px;display:grid;gap:12px;min-width:0}.site-editor-fields h3{font-size:18px;line-height:1.3;color:#6d3889;margin:16px 0 0}.site-section-editor{display:grid;gap:12px;background:#faf6fd;border:1px solid #e7d9ee;border-radius:14px;padding:15px}.site-preview-status{font-size:11px;color:#7a6389;line-height:1.5;min-height:17px}.site-help{font-size:12px;color:#807288;line-height:1.7}.site-button-editor{display:grid;grid-template-columns:1fr 1.5fr auto;gap:8px}.site-editor-preview{position:sticky;top:0;align-self:start;padding:20px;min-width:0;background:#f5f2f8;border-left:1px solid #e4d8ea}.site-preview-mobile{max-width:390px;margin:auto;border:5px solid #34243c;border-radius:20px;overflow:hidden}.site-editor-actions{position:sticky;bottom:0;background:white;border-top:1px solid #e5dcea;padding:14px;z-index:2}.site-switches{display:flex;flex-wrap:wrap;gap:10px}@media(max-width:1000px){.site-editor-grid{grid-template-columns:1fr}.site-editor-preview{position:static;border-left:0;border-top:1px solid #e4d8ea}.site-editor{max-width:100vw;border-radius:0}.site-library>header{align-items:stretch;flex-direction:column}.site-button-editor{grid-template-columns:1fr auto}.site-button-editor .q-field:nth-child(2){grid-column:1;grid-row:2}.site-button-editor .q-btn{grid-column:2;grid-row:1/3}.site-editor-fields{padding:14px}}</style>
